cd /workspace && python3 -c "
import json
def hook(pairs):
    d={}
    for k,v in pairs:
        if k in d: raise ValueError('dup')
        d[k]=v
    return d
def bad(s): raise ValueError('const')
print(json.loads('{\"a\":1,\"a\":2}', object_pairs_hook=hook))
try:
    json.loads('{\"a\":NaN}', object_pairs_hook=hook, parse_constant=bad)
except Exception as e: print('caught', type(e).__name__, e)
print(json.loads('1e999'))
print(type(json.loads('1e999')))
print(json.loads('{\"a\":1,\"a\":2}'))
"
